import{expect,test}from"bun:test";
import{Database}from"bun:sqlite";
import Ajv from"ajv";
import fixture from"../../🧫️fixtures/🪶️sqlite/🔣️.json";
import lawsSchema from"../../🧫️fixtures/🪶️sqlite/🧬️schema/🔣️.json";
import nativeSchema from"../../🔣️.json";
import * as owner from"../../🟦️.ts";
import{binary64}from"../../../../../../../../../../🔨️modules/🚪️io/🪶️sqlite-snapshot/🔢️ieee754/🟦️.ts";
import{exportSqliteDatabase,importSqliteDatabase,type SqliteDatabase}from"../../../../../../../../../../🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
import type{ArtifactSqliteOptions}from"../../../../../../../../../../🔨️modules/🚪️io/🪶️sqlite-snapshot/🧩️artifact/🟦️.ts";
type Snapshot=owner.WorkflowSnapshot;
function numeric(value:unknown){if(typeof value!=="number")throw Error("Neutral fixture requires a numeric field");return binary64(value)}
function optionalNumeric(value:unknown){return value===null?null:numeric(value)}
type Ports={workflowSnapshotToSqliteDatabase(value:Snapshot,options?:ArtifactSqliteOptions):Promise<SqliteDatabase>;workflowSnapshotFromSqliteDatabase(database:SqliteDatabase,options?:ArtifactSqliteOptions):Promise<Snapshot>};
const ports=owner as unknown as Ports;
function snapshot():Snapshot{
 const value=structuredClone(fixture.snapshot);
 return{...value,graph:{...value.graph,nodes:value.graph.nodes.map(node=>({...node,x:binary64(node.x),y:binary64(node.y),width:binary64(node.width),height:binary64(node.height),inputs:node.inputs as owner.WorkflowPort[],outputs:node.outputs as owner.WorkflowPort[]})),edges:value.graph.edges as owner.WorkflowEdge[]},parameters:value.parameters.map(parameter=>parameter.type==="numeric"?{...parameter,type:"numeric",value:binary64(parameter.value as number),min:optionalNumeric(parameter.min),max:optionalNumeric(parameter.max),step:optionalNumeric(parameter.step)}:parameter)as owner.WorkflowParameter[],inputs:value.inputs as Snapshot["inputs"]};
}
const bytes=async(value:Snapshot)=>exportSqliteDatabase(await ports.workflowSnapshotToSqliteDatabase(value));
const restore=async(value:Uint8Array,options:ArtifactSqliteOptions={})=>ports.workflowSnapshotFromSqliteDatabase(await importSqliteDatabase(value),options);
test("Workflow intrinsic wire preserves literal schemas and closes all three wire branches",async()=>{const cases=await Bun.file(new URL("../../🧫️fixtures/🪶️sqlite/🎞️wire/🔣️.json",import.meta.url)).json(),contract=await Bun.file(new URL("../../🧫️fixtures/🪶️sqlite/🎞️wire/🧬️schema/🔣️.json",import.meta.url)).json(),validator=new Ajv({strict:false,validateFormats:false}).addSchema(nativeSchema);expect(validator.validate(contract,cases)).toBe(true);for(const schema of cases.schemas){const expected=snapshot();expected.graph.edges[1]!.contract.wire={kind:"intrinsic",schema} as Snapshot["graph"]["edges"][number]["contract"]["wire"];const neutral=structuredClone(fixture.snapshot);neutral.graph.edges[1].contract.wire={kind:"intrinsic",schema} as typeof neutral.graph.edges[number]["contract"]["wire"];expect(validator.validate(nativeSchema,neutral)).toBe(true);const data=await bytes(expected),db=Database.deserialize(data,{safeIntegers:true});try{expect(db.query("SELECT wire_kind,format_kind,wire_schema FROM workflow_contract ORDER BY id DESC LIMIT 1").get()).toEqual({wire_kind:"intrinsic",format_kind:null,wire_schema:schema});expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected);expect(()=>db.run("UPDATE workflow_contract SET format_kind='invalid' WHERE wire_kind='intrinsic'")).toThrow()}finally{db.close()}}for(const wire of cases.invalid){const expected=structuredClone(fixture.snapshot);expected.graph.edges[1]!.contract.wire=wire;expect(validator.validate(nativeSchema,expected)).toBe(false)}});

test("Workflow independent neutral schema admits every persisted owner",()=>{const validator=new Ajv({strict:false,validateFormats:false}).addSchema(nativeSchema);expect(validator.validate(lawsSchema,fixture)).toBe(true)});
test("Workflow independent SQLite DDL declares sixteen tables without hidden indices",async()=>{const db=new Database(":memory:");try{db.run(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());expect(db.query("SELECT count(*) AS n FROM sqlite_master WHERE type='table'").get()).toEqual({n:16});expect(db.query("PRAGMA table_info(workflow_node)").all().length).toBe(22);expect(db.query("PRAGMA table_info(workflow_numeric)").all().length).toBe(14);expect(db.query("SELECT name FROM sqlite_master WHERE type='index'").all()).toEqual([])}finally{db.close()}});
test("Workflow public persisted facade exposes both semantic directions",()=>{expect(Object.hasOwn(owner,"workflowSnapshotToSqliteDatabase")).toBe(true);expect(Object.hasOwn(owner,"workflowSnapshotFromSqliteDatabase")).toBe(true)});
test("Workflow complete files preserve every literal duplicate and ordered collection",async()=>{const expected=snapshot(),data=await bytes(expected),db=Database.deserialize(data,{safeIntegers:true});try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT node_id FROM workflow_node ORDER BY ordinal").all()).toEqual([{node_id:""},{node_id:""}]);expect(db.query("SELECT value FROM workflow_category_option ORDER BY ordinal").all()).toEqual([{value:""},{value:""},{value:"\0😀"}]);expect(db.query("SELECT wire_kind,format_kind,wire_schema,conversion_from,conversion_to FROM workflow_contract ORDER BY id").all()).toEqual([{wire_kind:"binary",format_kind:"\0😀",wire_schema:null,conversion_from:14n,conversion_to:15n},{wire_kind:"document",format_kind:null,wire_schema:"",conversion_from:null,conversion_to:null}]);expect(await restore(data)).toEqual(expected)}finally{db.close()}});
for(const hex of fixture.binary64Words)test("Workflow exact node and parameter words "+hex,async()=>{const expected=snapshot(),word={bits:BigInt("0x"+hex)};for(const node of expected.graph.nodes)for(const key of["x","y","width","height"]as const)node[key]=word;const parameter=expected.parameters[0]!;if(parameter.type!=="numeric")throw Error("numeric fixture");parameter.value=word;parameter.min=word;parameter.max=word;parameter.step=word;const data=await bytes(expected),db=Database.deserialize(data,{safeIntegers:true});try{const buffer=Buffer.alloc(8);buffer.writeBigUInt64BE(word.bits);const number=buffer.readDoubleBE(),kind=Number.isNaN(number)?"nan":number===Infinity?"positiveInfinity":number===-Infinity?"negativeInfinity":"finite";expect(db.query("SELECT x_bits,x_class FROM workflow_node ORDER BY ordinal").all()).toEqual(expected.graph.nodes.map(()=>({x_bits:BigInt.asIntN(64,word.bits),x_class:kind})));expect(db.query("SELECT min_bits,min_class FROM workflow_numeric").get()).toEqual({min_bits:BigInt.asIntN(64,word.bits),min_class:kind});expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
test("Workflow optional numeric absence and optional literal kind differ from present empty",async()=>{for(const present of[false,true]){const expected=snapshot(),parameter=expected.parameters[0]!;if(parameter.type!=="numeric")throw Error("numeric fixture");parameter.min=present?{bits:0x7ff8000000000011n}:null;const spec=expected.graph.nodes[0]!.inputs[1]!.spec;if(present)spec.kindId="";else delete spec.kindId;expect(await restore(await bytes(expected))).toEqual(expected)}});
test("Workflow independent surrogate edits preserve ownership and editable literal fields",async()=>{const expected=snapshot(),db=Database.deserialize(await bytes(expected));try{db.run("UPDATE workflow_graph SET id=id+100");db.run("UPDATE workflow_node SET graph_id=graph_id+100,id=id+100,label='edited'");db.run("UPDATE workflow_port SET node_id=node_id+100,id=id+100");db.run("UPDATE workflow_edge SET graph_id=graph_id+100,id=id+100");db.run("UPDATE workflow_contract SET edge_id=edge_id+100,id=id+100");db.run("UPDATE workflow_parameter SET id=id+100");for(const table of["numeric","categorical","toggle","text"])db.run("UPDATE workflow_"+table+" SET parameter_id=parameter_id+100,id=id+100");db.run("UPDATE workflow_category_option SET categorical_id=categorical_id+100,id=id+100,value='edited'");for(const table of["parameter_binding","input","input_binding","output_binding"])db.run("UPDATE workflow_"+table+" SET id=id+100");for(const node of expected.graph.nodes)node.label="edited";const parameter=expected.parameters[1]!;if(parameter.type!=="categorical")throw Error("categorical fixture");parameter.options.fill("edited");expect(await restore(new Uint8Array(db.serialize()))).toEqual(expected)}finally{db.close()}});
for(const[index,sql]of fixture.malformedSql.entries())test("Workflow independent malformed semantic edit refuses "+index,async()=>{const db=Database.deserialize(await bytes(snapshot()));try{db.run("PRAGMA ignore_check_constraints=ON");db.run(sql);await expect(restore(new Uint8Array(db.serialize()))).rejects.toThrow()}finally{db.close()}});
test("Workflow full media enum domain retains all forms and classes",async()=>{const expected=snapshot();for(const value of fixture.mediaForms){expected.graph.nodes[0]!.inputs[0]!.spec.mediaType.form=value as owner.WorkflowMediaForm;expected.graph.edges[0]!.contract.conversion=[value as owner.WorkflowMediaForm,value as owner.WorkflowMediaForm];expect(await restore(await bytes(expected))).toEqual(expected)}for(const value of fixture.mediaClasses){expected.graph.nodes[0]!.inputs[0]!.spec.mediaType.class=value as owner.WorkflowMediaClass;expected.graph.edges[0]!.contract.mediaType.class=value as owner.WorkflowMediaClass;expect(await restore(await bytes(expected))).toEqual(expected)}},30000);
test("Workflow exact row equality is admitted and one below is refused",async()=>{const expected=snapshot(),database=await ports.workflowSnapshotToSqliteDatabase(expected),count=database.tables.reduce((sum,table)=>sum+table.rows.length,0);expect(count).toBe(30);await expect(ports.workflowSnapshotToSqliteDatabase(expected,{maxRows:count})).resolves.toBeDefined();await expect(ports.workflowSnapshotToSqliteDatabase(expected,{maxRows:count-1})).rejects.toThrow();await expect(ports.workflowSnapshotFromSqliteDatabase(database,{maxRows:count-1})).rejects.toThrow()});
